// spec: specs/gifts.md (раздел 6.3)
// seed: tests/seed.new02.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/new02.json'), colorScheme: 'dark' });

test.describe('Раунд 13: подарки (#47a8b8 #dc2c6f #676952 #e0de78)', () => {
  test('«המתנות ששלחתי»: «בתשלום» с ₪7.90, «מתגמול רצף» только бесплатные, тап → чат @iphone @prod-safe', async ({ page }) => {
    const rows = page.getByTestId('gift-history-row');
    const tab = (name: 'all' | 'paid' | 'reward') => page.getByTestId(`gift-history-filter-${name}`);

    // 1. `/settings` → «המתנות ששלחתי».
    await page.goto('/settings');
    await page.getByText('המתנות ששלחתי').click();
    await expect(page).toHaveURL(/\/gift\/history/);
    await expect(rows.first()).toBeVisible();

    // 2. Вкладка «בתשלום»; вкладка «מתגמול רצף»; вкладка «הכול».
    await tab('paid').click();
    await expect(rows.filter({ hasText: 'חינם' })).toHaveCount(0);
    const paidCount = await rows.count();
    expect(paidCount, 'нет платных отправок у new02 (ОКРУЖЕНИЕ)').toBeGreaterThan(0);
    await expect(rows.filter({ hasText: 'דובי פרחים' }).first()).toBeVisible();
    for (let i = 0; i < paidCount; i++) {
      const label = (await rows.nth(i).getAttribute('aria-label')) ?? '';
      expect(label, `платная строка ${i}: сумма ₪7.90`).toContain('₪7.90');
      expect(label, `платная строка ${i}: нет «חינם • תגמול רצף»`).not.toContain('חינם');
    }

    await tab('reward').click();
    await expect(rows.filter({ hasText: '₪' })).toHaveCount(0);
    await expect(rows.first()).toBeVisible();
    const rewardCount = await rows.count();
    for (let i = 0; i < rewardCount; i++) {
      const label = (await rows.nth(i).getAttribute('aria-label')) ?? '';
      expect(label, `строка награды ${i}`).toContain('חינם · תגמול רצף');
      expect(label, `строка награды ${i}: суммы нет`).not.toContain('₪');
    }

    await tab('all').click();
    await expect(rows.filter({ hasText: '₪7.90' }).first()).toBeVisible();
    await expect(rows.filter({ hasText: 'תגמול רצף' }).first()).toBeVisible();

    // 3. В «בתשלום» нажать строку.
    await tab('paid').click();
    await expect(rows.filter({ hasText: 'חינם' })).toHaveCount(0);
    await rows.first().click();
    await expect(page).toHaveURL(/\/chat\//);
  });
});
